package com.andye.warmod.icbm.client.render;
import com.andye.warmod.icbm.client.IcbmTrailSample;import com.andye.warmod.warhead.client.render.WarheadMesh;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.blaze3d.vertex.VertexConsumer;import java.util.List;import net.minecraft.util.Mth;import net.minecraft.world.phys.Vec3;import org.joml.Quaternionf;import org.joml.Vector3f;
public final class IcbmSmokeTrailRenderer {private IcbmSmokeTrailRenderer(){}public static void render(final PoseStack.Pose p,final VertexConsumer b,final List<IcbmTrailSample> samples,final WarheadMesh.Lod lod,final Quaternionf camera){int limit=lod==WarheadMesh.Lod.NEAR?120:lod==WarheadMesh.Lod.MEDIUM?70:32;int start=Math.max(0,samples.size()-limit);for(int i=start;i<samples.size();i++){IcbmTrailSample s=samples.get(i);float alpha=(float)Math.max(0,Math.min(.72,1-s.ageTicks()/140.0));float radius=s.size()*(float)(1+s.ageTicks()*.018);Vec3 c=s.position().add(s.drift().scale(s.ageTicks()));billboard(p,b,c,radius,s.rotation(),alpha,camera);}}private static void billboard(final PoseStack.Pose p,final VertexConsumer b,final Vec3 c,final float r,final float rotation,final float alpha,final Quaternionf camera){float co=Mth.cos(rotation),si=Mth.sin(rotation),ux=co*r,uy=si*r,vx=-si*r,vy=co*r;v(p,b,c,-ux-vx,-uy-vy,0,1,alpha,camera);v(p,b,c,-ux+vx,-uy+vy,0,0,alpha,camera);v(p,b,c,ux+vx,uy+vy,1,0,alpha,camera);v(p,b,c,ux-vx,uy-vy,1,1,alpha,camera);}private static void v(final PoseStack.Pose p,final VertexConsumer b,final Vec3 c,final float x,final float y,final float u,final float vv,final float alpha,final Quaternionf camera){Vector3f o=new Vector3f(x,y,0).rotate(camera),n=new Vector3f(0,0,1).rotate(camera);b.addVertex(p,(float)c.x+o.x,(float)c.y+o.y,(float)c.z+o.z).setColor(110,115,120,(int)(alpha*255)).setUv(u,vv).setOverlay(0).setLight(0xA000A0).setNormal(p,n.x,n.y,n.z);}}
